"""
F2: Report definitions — tabular reports built on SQL VIEWs.
"""
from datetime import datetime
from sqlalchemy import Column, Integer, String, Text, Boolean, DateTime, JSON, ForeignKey, func
from sqlalchemy.orm import relationship
from app.core.database import Base


class ReportDefinition(Base):
    __tablename__ = "report_definitions"

    id = Column(Integer, primary_key=True, index=True)
    name = Column(String(255), nullable=False)
    description = Column(Text, default="")
    
    # Source view (generated by F1)
    view_name = Column(String(100), nullable=False)  # e.g., "v_form_entry_form"
    
    # Report configuration
    columns = Column(JSON, default=list)  # [{field, label, type, aggregate}]
    filters = Column(JSON, default=list)  # [{field, operator, value}]
    sort_by = Column(String(100), default="")
    sort_order = Column(String(4), default="asc")  # asc, desc
    limit = Column(Integer, default=100)
    
    # Scheduling (optional)
    schedule_cron = Column(String(50), nullable=True)  # e.g., "0 9 * * *" for daily 9am
    export_format = Column(String(20), default="csv")  # csv, json
    
    # Ownership (A3)
    owner_user_id = Column(Integer, ForeignKey("users.id"), nullable=True)
    tags = Column(JSON, default=list)
    
    # Lifecycle
    is_active = Column(Boolean, default=True)
    created_at = Column(DateTime(timezone=True), server_default=func.now())
    updated_at = Column(DateTime(timezone=True), server_default=func.now(), onupdate=func.now())

    # Relationships
    owner = relationship("User", foreign_keys=[owner_user_id])
